#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using MVZ2.Metas;
using MVZ2Logic.Customize;
using MVZ2Logic.Models;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        public NamespaceID[] GetAllCustomizePageMetasID()
        {
            List<NamespaceID> list = new List<NamespaceID>();
            foreach (var modResource in modResources)
            {
                if (modResource.CustomizeMetaList == null)
                    continue;
                foreach (var page in modResource.CustomizeMetaList.pages)
                {
                    list.Add(new NamespaceID(modResource.Namespace, page.ID));
                }
            }
            return list.ToArray();
        }
        public CustomizePageMeta[] GetModCustomizePages(string spaceName)
        {
            var resources = GetModResource(spaceName);
            if (resources?.CustomizeMetaList == null)
                return Array.Empty<CustomizePageMeta>();
            return resources.CustomizeMetaList.pages.ToArray();
        }
        public CustomizePageMeta? GetCustomizePageMeta(NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            var resources = GetModResource(id.SpaceName);
            if (resources?.CustomizeMetaList == null)
                return null;
            return resources.CustomizeMetaList.pages.FirstOrDefault(e => e.ID == id.Path);
        }
        public CustomizePageController? GetCustomizePagePrefab(NamespaceID? id)
        {
            return FindInMods(id, m => m.CustomizePages);
        }
        private async Task LoadModCustomizePages(string nsp, TaskProgress progress)
        {
            var modResource = GetModResource(nsp);
            if (modResource == null)
                return;
            var resources = await LoadLabeledResources<GameObject>(nsp, "CustomizePage", progress);

            foreach (var (id, res) in resources)
            {
                var controller = res.GetComponent<CustomizePageController>();
                modResource.CustomizePages.Add(id.Path, controller);
            }
        }
    }
}
